{
  "revised_script": {
    "cold_open": "There is an old lighthouse near the sea, and sometimes its light turns on at night.",
    "question": "Why does it glow when no one is there?",
    "journey": "A boy from the village often watches the light flicker through the storm. He walks to the lighthouse on moonlit nights, drawn by the glow. Inside, he finds the old keeper's desk, untouched, with a journal and a faded photograph. The pages whisper of storms, of duty, of a man who once kept the light burning for ships lost at sea.",
    "discovery": "One night, the boy finds the lamp lit without a match. The journal speaks of a promise made to the sea, a vow to light the lamp until the storm passed. The boy realizes the keeper's spirit still lingers, bound to his duty.",
    "emotional_turn": "The boy feels the weight of the keeper's loneliness, the silence of the lighthouse echoing with unspoken words. He understands now why the light returns when the storm comes.",
    "payoff": "The boy lights the lamp himself, honoring the keeper's memory. The light shines on, guiding ships through the storm, as if the keeper had never left.",
    "after_image": "The lighthouse stands, quiet and watchful, in the morning light."
  },
  "edits": [
    {
      "where": "cold_open",
      "change": "Removed the explanation about the moon reflecting on glass, which undermined the mystery.",
      "why": "The mystery is essential to the story's emotional core and must be preserved."
    },
    {
      "where": "question",
      "change": "Replaced vague curiosity with a direct, compelling question.",
      "why": "A strong question drives the narrative and focuses the reader's attention."
    },
    {
      "where": "journey",
      "change": "Added the boy's exploration of the lighthouse and the keeper's journal, which provides depth and context.",
      "why": "This strengthens the emotional and narrative journey, making the boy's experience more meaningful."
    },
    {
      "where": "discovery",
      "change": "Introduced the journal and the keeper's promise, which connects the boy's actions to the lighthouse's mystery.",
      "why": "This creates a meaningful link between the past and present, repairing the weak connection in the original draft."
    },
    {
      "where": "emotional_turn",
      "change": "Shifted focus to the boy's emotional realization of the keeper's loneliness.",
      "why": "This deepens the emotional impact and gives the story a more human dimension."
    },
    {
      "where": "payoff",
      "change": "Replaced the passive resolution with the boy taking action, honoring the keeper's memory.",
      "why": "This gives the central question a satisfying and earned resolution."
    },
    {
      "where": "after_image",
      "change": "Simplified the ending to focus on the lighthouse's enduring presence.",
      "why": "This creates a lasting, poetic image that lingers in the reader's mind."
    }
  ],
